EXEC sp_addextendedproperty @name = N'MS_Description', @value = N'The first occurrence holds the premium for the base coverage. The second occurrence holds the premium for any ADB coverage. The third occurrence holds the premium for the WP coverage.  For interest sensitive products, the cost of insurance (COI) charge is usually used.  This premium is used to calculate reinsurance premiums for coinsured cessions. In most cases, the direct policy fee should not be included in the premium. The premium should be annual, with no modal factors.  The fields for insured data occur two times, once for each insured on a coverage. Unused occurrences of insured data should be initialized to spaces and zeroes.', @level0type = N'SCHEMA', @level0name = N'dbo', @level1type = N'TABLE', @level1name = N'TAI_REINS_HIST_POLICY', @level2type=N'COLUMN', @level2name=N'TAIX_PREM_1';
GO
EXEC sp_addextendedproperty @name = N'MS_Description', @value = N'ADB', @level0type = N'SCHEMA', @level0name = N'dbo', @level1type = N'TABLE', @level1name = N'TAI_REINS_HIST_POLICY', @level2type=N'COLUMN', @level2name=N'TAIX_PREM_2';
GO
EXEC sp_addextendedproperty @name = N'MS_Description', @value = N'Plan code field wider if didn’t fit could place here.  TX-Plan 15 above', @level0type = N'SCHEMA', @level0name = N'dbo', @level1type = N'TABLE', @level1name = N'TAI_REINS_HIST_POLICY', @level2type=N'COLUMN', @level2name=N'TAIX_SEARCH_PLAN';
GO
EXEC sp_addextendedproperty @name = N'MS_Description', @value = N'Client ID used to uniquely identify an insured. If not available on the administrative system, a client ID will be assigned by TAI.', @level0type = N'SCHEMA', @level0name = N'dbo', @level1type = N'TABLE', @level1name = N'TAI_REINS_HIST_POLICY', @level2type=N'COLUMN', @level2name=N'TAIX_CLIENT_ID_1';
GO
EXEC sp_addextendedproperty @name = N'MS_Description', @value = N'The last name, first name, and middle initial of the insured. The name on the rider may be different than the one on the basic coverage. A ‘relationship’ code of some type will identify the correct name for the insured.  The name will frequently be stored in a format incompatible with the reinsurance system format, usually first, last and middle initial in one field separated by spaces or commas. If the administrative system contains a module to break up the name, or if code can be copied from another program, it should be used.  The last name must be separated for sorting/reporting purposes. If the first name/middle initial cannot be separated, they should both be moved to the first name field, and the initial left blank. All letters in the name fields must be uppercased.', @level0type = N'SCHEMA', @level0name = N'dbo', @level1type = N'TABLE', @level1name = N'TAI_REINS_HIST_POLICY', @level2type=N'COLUMN', @level2name=N'TAIX_LAST_NAME_1';
GO
EXEC sp_addextendedproperty @name = N'MS_Description', @value = N'Gender used to compute premiums on the administrative system. It is usually the same as the insured’s gender, but it may be different if unisex rates are used. This is the gender that will be used to compute reinsurance premiums', @level0type = N'SCHEMA', @level0name = N'dbo', @level1type = N'TABLE', @level1name = N'TAI_REINS_HIST_POLICY', @level2type=N'COLUMN', @level2name=N'TAIX_PRICING_GENDER_1';
GO
